        name,
        isDir,
        method,
        crc32: memberCrc32,
        compressedSize,
        uncompressedSize,
        size: uncompressedSize,
        localHeaderOffset,
        modifiedIso: _dosDateTimeToIso(modDate, modTime),
        versionMadeBy,
