/* meldex-core.part01.js */
/**
 * Meldex Core Library
 * 共通ユーティリティ・アイコン・テーマ・API通信
 * Meldex.html, calendar.html, canvas.html 等から共有利用
 *
 * 使い方: <script src="meldex-core.js"></script>
 * グローバルに関数・定数を公開（Meldex.htmlとの互換性のため）
 */

// ============================================================
// API通信
// ============================================================
const API_BASE = window.MeldexRuntimeAdapter?.getApiBaseUrl?.() || '/api';
const API_FETCH_BROWSE_CACHE_TTL_MS = 2500;
const API_FETCH_TIMEOUT_MS = 15000; // fetch()がハングし続け、フォルダツリー等が無限ロードになるのを防ぐ上限
const API_FETCH_MAX_TIMEOUT_MS = 330000;
// OSネイティブの選択ダイアログは利用者の操作を待つ。通常APIの15秒で中断すると、
// 選択済みのパスを受け取れず再入力を要求するため、サーバー待機上限より長く保つ。
const API_FETCH_NATIVE_DIALOG_TIMEOUTS = new Map([
  ['/pick-folder', 135000],
  ['/add-outliner-root', 135000],
  ['/dropbox-link/pick-workspace-folder', 135000],
  ['/workspaces/pick-folder', 135000],
  ['/standalone/pick-folder', 135000],
  ['/save-file-dialog', 315000],
  ['/open-file-dialog', 315000],
  ['/settings-transfer/export', 315000],
]);
function _apiFetchDefaultTimeout(path) {
  const pathname = String(path || '').split('?')[0];
  return API_FETCH_NATIVE_DIALOG_TIMEOUTS.get(pathname) || API_FETCH_TIMEOUT_MS;
}
const _apiFetchBrowseCache = new Map();
const _apiFetchBrowseInFlight = new Map();
let _apiFetchBrowseCacheGeneration = 0;

// シートのIME変換中キーは、後から登録されたメニュー／ショートカットの
// Escape・Enter処理より先に止める。既定動作はキャンセルせずIMEへ渡す。
function _meldexProtectSheetImeKeyEvent(event) {
  if (!(event?.isComposing || event?.keyCode === 229)) return;
  if (!event.target?.closest?.('td[data-prop-name]')) return;
  event.stopPropagation();
  event.stopImmediatePropagation?.();
}
window.addEventListener('keydown', _meldexProtectSheetImeKeyEvent, true);

function _apiFetchMethod(opts) {
  return String(opts?.method || 'GET').toUpperCase();
}

function _apiFetchClonePayload(payload) {
  if (typeof structuredClone === 'function') {
    try { return structuredClone(payload); } catch {}
  }
  try { return JSON.parse(JSON.stringify(payload)); } catch { return payload; }
}

function _apiFetchBrowseCacheKey(path, opts) {
  if (_apiFetchMethod(opts) !== 'GET' || opts?.body != null || opts?.skipBrowseCache === true || opts?.cache === 'reload' || opts?.signal) return '';
  try {
    const url = new URL(API_BASE.replace(/\/+$/, '') + path, window.location.origin || 'http://localhost');
    const apiBasePath = new URL(API_BASE, window.location.origin || 'http://localhost').pathname.replace(/\/+$/, '');
    if (url.pathname !== apiBasePath + '/browse') return '';
    const params = [...url.searchParams.entries()]
      .sort(([ak, av], [bk, bv]) => (ak + '=' + av).localeCompare(bk + '=' + bv));
    return url.pathname + '?' + params.map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value)).join('&');
  } catch {
    return '';
  }
}

function _apiFetchInvalidateBrowseCache() {
  _apiFetchBrowseCacheGeneration += 1;
  _apiFetchBrowseCache.clear();
  _apiFetchBrowseInFlight.clear();
}

async function apiFetch(path, opts) {
  const cacheKey = _apiFetchBrowseCacheKey(path, opts);
  const cacheGeneration = _apiFetchBrowseCacheGeneration;
  if (!cacheKey && _apiFetchMethod(opts) !== 'GET') _apiFetchInvalidateBrowseCache();
  if (cacheKey) {
    const cached = _apiFetchBrowseCache.get(cacheKey);
    if (cached && Date.now() - cached.at < API_FETCH_BROWSE_CACHE_TTL_MS) {
      return _apiFetchClonePayload(cached.payload);
    }
    _apiFetchBrowseCache.delete(cacheKey);
    const inFlight = _apiFetchBrowseInFlight.get(cacheKey);
    if (inFlight) return _apiFetchClonePayload(await inFlight);
  }
  let requestPromise = null;
  const controller = new AbortController();
  const requestedTimeout = Number(opts?.timeoutMs);
  const timeoutMs = Number.isFinite(requestedTimeout) && requestedTimeout > 0
    ? Math.min(requestedTimeout, API_FETCH_MAX_TIMEOUT_MS)
    : _apiFetchDefaultTimeout(path);
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
  try {
    requestPromise = (async () => {
      const fetchOpts = opts ? { ...opts, signal: controller.signal } : { signal: controller.signal };
      delete fetchOpts.timeoutMs;
      const fullUrl = API_BASE.replace(/\/+$/, '') + path;
      const res = await fetch(fullUrl, fetchOpts);
      if (!res.ok) {
        let detail = '';
        try {
          const raw = await res.text();
          if (raw) {
            try {
              const payload = JSON.parse(raw);
              detail = payload?.detail || payload?.error || payload?.message || raw;
            } catch {
              detail = raw;
            }
          }
        } catch {}
        detail = String(detail || '').replace(/\s+/g, ' ').trim().slice(0, 500);
        const error = new Error(`HTTP ${res.status}: ${res.statusText}${detail ? ` — ${detail}` : ''}`);
        error.status = res.status;
        throw error;
      }
      const json = await res.json();
      return json;
    })();
    if (cacheKey) _apiFetchBrowseInFlight.set(cacheKey, requestPromise);
    const payload = await requestPromise;
    clearTimeout(timeoutId);
    if (cacheKey && cacheGeneration === _apiFetchBrowseCacheGeneration) {
      _apiFetchBrowseCache.set(cacheKey, { at: Date.now(), payload: _apiFetchClonePayload(payload) });
      while (_apiFetchBrowseCache.size > 80) {
        const firstKey = _apiFetchBrowseCache.keys().next().value;
        if (!firstKey) break;
        _apiFetchBrowseCache.delete(firstKey);
      }
    }
    return _apiFetchClonePayload(payload);
  } catch (e) {
    if (e.name === 'AbortError') {
      // タイムアウト/中断はエラートースト表示せず、コンソールログのみに留める（呼び出し元は再試行等で処理する）
      try { console.warn('[apiFetch] timed out or aborted:', path); } catch {}
      const err = new Error(`リクエストがタイムアウトしました（${Math.round(timeoutMs / 1000)}秒）`);
      err.name = 'AbortError';
      err.isTimeout = true;
      throw err;
    }
    if (!opts?.silentError && typeof showStatus === 'function') showStatus('エラー: ' + e.message, true);
    throw e;
  } finally {
    clearTimeout(timeoutId);
    if (cacheKey && _apiFetchBrowseInFlight.get(cacheKey) === requestPromise) _apiFetchBrowseInFlight.delete(cacheKey);
  }
}

async function _meldexCorePrepareFileWrite(path, body) {
  const payload = { ...(body || {}) };
  const endpoint = String(path || '').split('?', 1)[0].replace(/^\/api/, '');
  const isFullWrite = endpoint === '/file'
    && (Object.prototype.hasOwnProperty.call(payload, 'content')
      || Object.prototype.hasOwnProperty.call(payload, 'content_base64'));
  if (!isFullWrite || payload.force_overwrite || payload.forceOverwrite
    || payload.create_only || payload.createOnly) return payload;
  const coordinator = window.MeldexDocumentSaveCoordinator;
  const supplied = payload.transport_revision || payload.transportRevision
    || payload.if_match_etag || payload.ifMatchEtag || '';
  if (supplied) {
    if (coordinator?.revisionTokenForWrite) payload.if_match_etag = coordinator.revisionTokenForWrite(supplied);
    return payload;
  }
  // 既存ファイルの最新revisionをここで拾って古い本文へ付け直すと、外部更新を
  // 未確認のまま上書きできてしまう。自動補完は新規作成時のcreate_onlyだけ。
  try {
    const separator = String(path).includes('?') ? '&' : '?';
    const metadata = await apiFetch(`${path}${separator}metadata_only=1`, { silentError: true });
    const error = new Error('既存ファイルの保存には、読込時のrevisionが必要です');
    error.status = 428;
    error.meldexCode = 'precondition_required';
    error.meldexDetail = {
      code: 'precondition_required',
      path: new URLSearchParams(String(path).split('?')[1] || '').get('path') || '',
      current_etag: metadata?.etag || '',
      current_transport_revision: metadata?.transport_revision || null,
    };
    throw error;
  } catch (error) {
    if (error?.status === 404 && !(payload.skip_if_missing || payload.skipIfMissing)) {
      payload.create_only = true;
      return payload;
    }
    if (error?.status === 404 && (payload.skip_if_missing || payload.skipIfMissing)) return payload;
    throw error;
  }
}

async function apiPut(path, body) {
  const guardedBody = await _meldexCorePrepareFileWrite(path, body);
  const result = await apiFetch(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(guardedBody),
  });
  _scheduleLinkDictionaryRefreshForMutation(path);
  return result;
}

function _scheduleLinkDictionaryRefreshForMutation(path) {
  const pathname = String(path || '').split('?')[0];
  if (![
    '/value', '/entity/create', '/entity/rename',
    '/outliner/delete', '/outliner/delete-batch', '/outliner/rename',
  ].includes(pathname)) return;
  if (typeof MeldexAutoLink !== 'undefined' && typeof MeldexAutoLink.scheduleReload === 'function') {
    MeldexAutoLink.scheduleReload(3000);
  }
}

async function apiPost(path, body, options = {}) {
  let stableCopyKey = '';
  if (['/outliner/duplicate', '/outliner/save-as'].includes(String(path || ''))
      && body && typeof body === 'object' && !body.operation_id) {
    const prepared = window.MeldexStableCopyOperationIds?.prepare?.(path, body)
      || { body: { ...body, operation_id: crypto.randomUUID() }, key: '' };
    body = prepared.body; stableCopyKey = prepared.key;
  }
  const result = await apiFetch(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    ...(options || {}),
  });
  window.MeldexStableCopyOperationIds?.complete(stableCopyKey);
  _scheduleLinkDictionaryRefreshForMutation(path);
  return result;
}

async function apiDelete(path) {
  return apiFetch(path, { method: 'DELETE' });
}

// OSネイティブの「ファイルを開く」ダイアログを表示し、選択されたパスを返す（キャンセル時は空文字列）
async function openFileDialog(title, initialdir, filetypes) {
  const resp = await apiPost('/open-file-dialog', { title, initialdir, filetypes });
  return resp?.path || '';
}

