    begin: begin,
    get: get,
    findByPersistentJobId: findByPersistentJobId,
    list: list,
    subscribe: subscribe,
    requestCancel: requestCancel,
    retry: retry,
    isTerminalStatus: function (status) { return TERMINAL.has(String(status || '')); },
